                                                                                                                                                                                                                                                                                                            // =====================================
                                                                                                                                                                                                                                                                                                            // CHAT AI HANDLER
                                                                                                                                                                                                                                                                                                            // =====================================

                                                                                                                                                                                                                                                                                                            void handleChat() {

                                                                                                                                                                                                                                                                                                              if (!server.hasArg("plain")) {
                                                                                                                                                                                                                                                                                                                  server.send(400, "application/json",
                                                                                                                                                                                                                                                                                                                        "{\"error\":\"Pesan kosong\"}");
                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                DynamicJsonDocument inputDoc(2048);

                                                                                                                                                                                                                                                                                                                                  DeserializationError inputError =
                                                                                                                                                                                                                                                                                                                                      deserializeJson(inputDoc, server.arg("plain"));

                                                                                                                                                                                                                                                                                                                                        if (inputError) {
                                                                                                                                                                                                                                                                                                                                            server.send(400, "application/json",
                                                                                                                                                                                                                                                                                                                                                  "{\"error\":\"JSON tidak valid\"}");
                                                                                                                                                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                          String message = inputDoc["message"] | "";

                                                                                                                                                                                                                                                                                                                                                            if (message.length() == 0 || message.length() > 1500) {
                                                                                                                                                                                                                                                                                                                                                                server.send(400, "application/json",
                                                                                                                                                                                                                                                                                                                                                                      "{\"error\":\"Pesan kosong atau terlalu panjang\"}");
                                                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                              if (WiFi.status() != WL_CONNECTED) {
                                                                                                                                                                                                                                                                                                                                                                                  server.send(503, "application/json",
                                                                                                                                                                                                                                                                                                                                                                                        "{\"error\":\"ESP32 belum terhubung ke internet\"}");
                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                WiFiClientSecure client;

                                                                                                                                                                                                                                                                                                                                                                                                  // Untuk prototipe saja.
                                                                                                                                                                                                                                                                                                                                                                                                    // Produksi sebaiknya menggunakan validasi sertifikat TLS.
                                                                                                                                                                                                                                                                                                                                                                                                      client.setInsecure();

                                                                                                                                                                                                                                                                                                                                                                                                        HTTPClient https;

                                                                                                                                                                                                                                                                                                                                                                                                          https.setTimeout(30000);

                                                                                                                                                                                                                                                                                                                                                                                                            if (!https.begin(client, API_URL)) {
                                                                                                                                                                                                                                                                                                                                                                                                                server.send(500, "application/json",
                                                                                                                                                                                                                                                                                                                                                                                                                      "{\"error\":\"Gagal menghubungi server AI\"}");
                                                                                                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                              https.addHeader("Content-Type", "application/json");

                                                                                                                                                                                                                                                                                                                                                                                                                                https.addHeader(
                                                                                                                                                                                                                                                                                                                                                                                                                                    "Authorization",
                                                                                                                                                                                                                                                                                                                                                                                                                                        String("Bearer ") + OPENROUTER_API_KEY
                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                            https.addHeader("HTTP-Referer", "http://192.168.4.1");
                                                                                                                                                                                                                                                                                                                                                                                                                                              https.addHeader("X-Title", "DEWZX AI");

                                                                                                                                                                                                                                                                                                                                                                                                                                                DynamicJsonDocument requestDoc(4096);

                                                                                                                                                                                                                                                                                                                                                                                                                                                  requestDoc["model"] = MODEL;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    requestDoc["temperature"] = 0.7;
                                                                                                                                                                                                                                                                                                                                                                                                                                                      requestDoc["max_tokens"] = 700;

                                                                                                                                                                                                                                                                                                                                                                                                                                                        JsonArray messages =
                                                                                                                                                                                                                                                                                                                                                                                                                                                            requestDoc.createNestedArray("messages");

                                                                                                                                                                                                                                                                                                                                                                                                                                                              JsonObject systemMessage =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  messages.createNestedObject();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    systemMessage["role"] = "system";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                      systemMessage["content"] =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "Kamu adalah DEWZX AI, asisten AI yang ramah, "
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "cerdas, cepat, dan membantu. Jawab menggunakan "
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "bahasa Indonesia yang mudah dipahami.";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    JsonObject userMessage =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        messages.createNestedObject();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          userMessage["role"] = "user";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            userMessage["content"] = message;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              String body;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                serializeJson(requestDoc, body);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  int httpCode = https.POST(body);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    String response = https.getString();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      https.end();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (httpCode <= 0) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            server.send(502, "application/json",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "{\"error\":\"Koneksi ke server AI gagal\"}");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (httpCode != 200) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              DynamicJsonDocument errorDoc(2048);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  String errorMessage = "Server AI mengembalikan error.";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!deserializeJson(errorDoc, response)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            errorMessage =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    errorDoc["error"]["message"] | errorMessage;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            DynamicJsonDocument outputDoc(2048);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                outputDoc["error"] = errorMessage;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    String output;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        serializeJson(outputDoc, output);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            server.send(httpCode, "application/json", output);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    DynamicJsonDocument responseDoc(12000);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      DeserializationError responseError =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          deserializeJson(responseDoc, response);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (responseError) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                server.send(502, "application/json",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "{\"error\":\"Jawaban AI tidak dapat dibaca\"}");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              String answer =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  responseDoc["choices"][0]["message"]["content"] |
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "AI tidak memberikan jawaban.";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        DynamicJsonDocument outputDoc(10000);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          outputDoc["reply"] = answer;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            String output;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              serializeJson(outputDoc, output);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                server.send(200, "application/json", output);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // =====================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // SETUP
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // =====================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                void setup() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.begin(115200);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    WiFi.mode(WIFI_AP_STA);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Membuat WiFi DEWZX AI
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        WiFi.softAP(AP_NAME, AP_PASSWORD);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Serial.println();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Serial.println("===== DEWZX AI =====");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Serial.print("WiFi AP: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Serial.println(AP_NAME);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.print("Password: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Serial.println(AP_PASSWORD);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Serial.print("Alamat AP: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Serial.println(WiFi.softAPIP());

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // Menghubungkan ESP32 ke internet
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (strlen(WIFI_SSID) > 0) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                WiFi.begin(WIFI_SSID, WIFI_PASS);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Serial.print("Menghubungkan ke WiFi");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        unsigned long startTime = millis();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            while (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  WiFi.status() != WL_CONNECTED &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        millis() - startTime < 20000
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  delay(500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Serial.print(".");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (WiFi.status() == WL_CONNECTED) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Serial.println();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Serial.println("Internet berhasil terhubung!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.print("IP Internet: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Serial.println(WiFi.localIP());

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.println();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Serial.println("Gagal terhubung ke internet.");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Halaman utama
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  server.on("/", HTTP_GET, []() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      server.send_P(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            200,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "text/html",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        INDEX_HTML
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Endpoint AI
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  server.on("/chat", HTTP_POST, handleChat);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    server.begin();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Serial.println("Web server aktif!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // =====================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // LOOP
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // =====================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      void loop() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        server.handleClient();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
